def gen(rng):
    def build(n, lo=1, hi=10**9):
        vals = sorted(rng.sample(range(lo, hi + 1), n))
        res = [0] * n
        it = iter(vals)
        def inorder(i):
            if i >= n:
                return
            inorder(2 * i + 1)
            res[i] = next(it)
            inorder(2 * i + 2)
        inorder(0)
        return ' '.join(map(str, res))
    tests = [build(1), build(2), build(3), build(4), build(7, 1, 7), build(6, 1, 6)]
    for n in range(5, 30):
        tests.append(build(n, 1, rng.choice([n, 100, 10**9])))
    for n in (31, 32, 63):
        tests.append(build(n, 1, 10**9))
    tests.append(build(100000))
    tests.append(build(99999))
    tests.append(build(65535))
    tests.append(build(65536))
    return tests
